def definitelyExcludes(x: Type, y: Type): Boolean =
  isTrue(excludes(x,y))

def dExc(x: Type, y: Type)(implicit history: Set[hType]): Boolean = isTrue(exc(x,y))

/*
 * Given two types x and y this method computes the constraints
 * under which x and y do not exclude one another. For example if
 * we have x=List[\$i\] and y=List[\$k\] then x and y exclude one another
 * unless $i=$j. Note that this method only generates equality constraints.
 */
def notExcludes(x: Type , y: Type): CFormula = nExc(normalize(x), normalize(y))(Set())

protected def nExc(x: Type, y: Type)(implicit history: Set[hType]): CFormula = 
  pExc(x,y)(true, history)

/** Determine if a collection of types all exclude each other. */
def allExclude(ts: Iterable[Type]): CFormula =
  and(Pairs.distinctPairsFrom(ts).map(tt => excludes(tt._1, tt._2)))

def anyExclude(ts: Iterable[Type]):CFormula =
  or(Pairs.distinctPairsFrom(ts).map(tt => excludes(tt._1, tt._2)))


private val pExcMemo = new scala.collection.mutable.HashMap[(Type, Type, Boolean, Set[hType]), CFormula]()

protected def pExc(x: Type, y: Type)(implicit negate: Boolean, history: Set[hType]): CFormula = {
  if (x == y) pFalse()
  else if (cacheExcludes)
    pExcMemo.get((x, y, negate, history)) match {
      case Some(v) => v
      case _ => 
        val result = pExcInner(x,y)
        pExcMemo += ((x, y, negate, history) -> result)
        result
    }
  else pExcInner(x,y)
}

protected def pExcInner(x: Type, y: Type)(implicit negate: Boolean, history: Set[hType]): CFormula = (removeSelf(x), removeSelf(y)) match {
  case (s: BottomType, _) => pTrue()
  case (_, t: BottomType) => pTrue()
  case (s: AnyType, t) => pSub(t, BOTTOM)
  case (s, t: AnyType) => pSub(s, BOTTOM)
  case (s@SIntersectionType(_, elts), t) =>
    pOr(pSub(s, BOTTOM), pOr(elts.map(pExc(_, t))))
  case (s, t: IntersectionType) => exc(t, s)
  case (s@SUnionType(_, elts), t) =>
    pAnd(elts.map(pExc(_, t)))
  case (s, t: UnionType) => exc(t, s)
  case (i: _InferenceVarType, j: _InferenceVarType) if i==j => pFalse()
  case (i: _InferenceVarType, j: _InferenceVarType) => pAnd(pExclusion(i,j), pExclusion(j,i))
  case (i: _InferenceVarType, t) => pExclusion(i, t)
  case (s, j: _InferenceVarType) => pExc(j, s)
  case (s@SVarType(_, sid, _), t@SVarType(_, tid, _)) if (s==t || sid == tid) =>
    pOr(pSub(s, BOTTOM), pSub(t, BOTTOM))
  case (s@SVarType(_, id, _), t) =>
    val hEntry = (negate, false, s, t)
    if (history.contains(hEntry))
      False
    else {
      val nHistory = history + hEntry
      val sParam = staticParam(id)
      val supers = pNorm(makeIntersectionType(toListFromImmutable(sParam.getExtendsClause)))
      if (negate) pFalse()(!negate) else pExc(supers, t)(negate, nHistory)
    }
  case (s, t:VarType) => exc(t, s)
  // TODO: Check what happens when stem s = stem t
  case (s: TraitType, t: TraitType) =>
    def checkEC(s: TraitType, t: TraitType): CFormula = {
      def cEC(s: TraitType, t: TraitType) = pOr(excludesClause(s).map(pSub(t, _)))
      pOr(cEC(s, t), cEC(t, s))
    }
    def checkCC(s: TraitType, t: TraitType): CFormula = {
      def cCC(s: TraitType, t: TraitType): CFormula = {
        val scc = comprisesClause(s)
        pAnd(pFromBoolean(!scc.isEmpty), pAnd(scc.map(pExc(t,_))))
      }
      pOr(cCC(s, t), cCC(t, s))
    }
    def checkO(s: TraitType, t: TraitType): CFormula = {
      def cO(s: TraitType, t: TraitType): CFormula = typeCons(s.getName) match {
        case _:ObjectTraitIndex => pSub(s, t)(!negate, history)
        case _ => pFalse()
      }
      pOr(cO(s,t), cO(t,s))
    }
    def checkP(s: TraitType, t: TraitType): CFormula = {
      val sas = ancestors(s) ++ Set(s)
      val tas = ancestors(t) ++ Set(t)
      def cP(s: BaseType, t: BaseType): CFormula = (s, t) match {
        case (s@STraitType(_, n1, a1, _), t@STraitType(_, n2, a2, _)) if (n1 == n2) =>
          //Todo: Handle int, nat, bool args
          pOr((a1, a2).zipped.map{
            case (STypeArg(_, _, t1), STypeArg(_, _, t2)) => pEqv(t1, t2)(!negate, history)
            case _ => pFalse()
          })
        case _ => pFalse()
      }
      pOr(for(sa <- sas; ta <- tas) yield cP(sa, ta))
    }
    pOr(List(checkEC(s,t), checkCC(s,t), checkO(s,t), checkP(s,t)))
  // ToDo: Handle keywords. Note that this will mean you can have a tuple of length 1 without varargs.
  case (s@STupleType(_, e1, Some(v1), _), t@STupleType(_, e2, mv2, _)) =>
      pExc(disjunctFromTuple(s, max(e1.size, e2.size)), t)
  case (s@STupleType(_, e1, None, _), t@STupleType(_, e2, Some(v2), _)) => pExc(t, s)
  case (STupleType(_, e1, None, _), STupleType(_, e2, None, _)) if (e1.size == e2.size) =>
    pOr((e1, e2).zipped.map((a, b) => pExc(a, b)))
  case (STupleType(_, e1, None, _), STupleType(_, e2, None, _)) =>
    pTrue()
  case (s: TupleType, t) => pExc(disjunctFromTuple(s, 1), t)
  case (s, t: TupleType) => pExc(t, s)
  case (s: ArrowType, t: ArrowType) => pFalse()
  case (s: ArrowType, t) => pTrue()
  case (s, t: ArrowType) => pExc(t, s)

	// println("checkDeclComprises" + ti.ast)
	val self_type = ti.typeOfSelf.unwrap
	val tt = SNodeUtil.getTraitType(self_type) match {
	  case Some(traitTy) => traitTy
	  case _ =>
	    error(errors, "Invalid trait type: " + self_type, decl)
	    Types.OBJECT // error recovery
	}
	val new_analyzer = analyzer.extend(toListFromImmutable(ti.staticParameters), None)
	val extended = toListFromImmutable(ti.extendsTypes)
	for (extension <- extended) {
	  extension match {
	    // TODO: Extend to handle non-empty where clauses.
	    case STraitTypeWhere(_,SAnyType(_),_) => {}
	    case STraitTypeWhere(_,st@STraitType(_,name,_,_),_) =>
	      for (second <- extended) {
		second match {
		  case STraitTypeWhere(_,other@STraitType(_,_,_,_),_) =>
		    if ( new_analyzer.definitelyExcludes(st, other) )
		      error(errors, "Types " + st + " and " + other +
			    " exclude each other.  " + decl +
			    " must not extend them.", st)
		  case _ =>
		}
	      }
	      getTypes(name, errors) match {
		case si:ProperTraitIndex =>
		  if ( new_analyzer.definitelyExcludes(tt, st) ) {
		      error(errors, "Type " + tt + " excludes " + name +
			    " but it extends " + name + ".", extension)
		  }
		  val comprises = toSet(si.comprisesTypes)
		  SNodeUtil.validComprises(comprises, si.staticParameters) match {
		    case Some(tv) =>
		      error(errors, tv + " is a naked type variable in the " +
			    "comprises clause of a trait " + name + "\n    but " +
			    "it is not a static parameter of " + name + ".", extension)
		    case _ =>
		  }
		  val subst_comprises =
		    comprises.map(substitute(toListFromImmutable(st.getArgs),
					     toListFromImmutable(si.staticParameters),
					     _).asInstanceOf[NamedType])
		  if (! comprises.isEmpty &&
		      ! isEligibleToExtend(tt, subst_comprises, new_analyzer, errors) &&
		      ! NodeUtil.isComprisesEllipses(si.ast) )
		    error(errors, "Invalid comprises clause: " + name +
			  " has a comprises clause\n    but its immediate subtype " + decl +
			  " is not eligible to extend it.", ti.ast)
		  if ( isApi && NodeUtil.isComprisesEllipses(si.ast) )
		    error(errors, "Invalid comprises clause: " +
                          "a trait with a comprises ...,\n    such as " + name +
			  ", should not be extended.", ti.ast)
		case _ => error(errors, "Invalid type in extends clause: " +
				extension.getBaseType, extension)
	      }

            if(!errors.isEmpty())
                return new TypeCheckerResult(ast,errors);
        }

        // Pass 'false' argument to TypeNormalizer constructor to indicate that 
        // additional bounds should not be added to naked type parameters that also 
        // appear naked in the comprises clause. (That conversion is now done in
        // PreDisambiguationDesugarPhase, in order to correct a bug in checking
        // that static arguments satisfy the corresponding parameters' bounds.
        // EricAllen 4/27/2011
        ast = (CompilationUnit)ast.accept(new TypeNormalizer());
        index = buildIndex(ast, isApi);

        TraitTable traitTable = new TraitTable(index, env);
        TypeAnalyzer typeAnalyzer = com.sun.fortress.scala_src.types.TypeAnalyzer$.MODULE$.make(traitTable);

        if (Shell.testCoercion())
            errors.addAll(new CoercionTest(typeAnalyzer).run());

        errors.addAll(typeHierarchyChecker.checkAcyclicHierarchy(typeAnalyzer));
        errors.addAll(new TypeWellFormedChecker(index, env, typeAnalyzer).check());

        TypeCheckerResult result;
        if (isApi) {
            result = new TypeCheckerResult(ast, errors);
        } else {
            ComponentIndex componentIndex = (ComponentIndex)index;
            Component component_ast = (Component)ast;
            if ( ! Shell.getScala() ) {
                throw new Error("The Java version of the type checker is gone now.");
            } else {
                STypeEnv typeEnv = com.sun.fortress.scala_src.typechecker.staticenv.STypeEnv$.MODULE$.make(componentIndex);
                ErrorLog log = new ErrorLog();

                //Create thunks for when the user elides function return types
                CyclicReferenceChecker cycleChecker = new CyclicReferenceChecker(log);
                STypeChecker thunkChecker =
                  STypeCheckerFactory.make(componentIndex, traitTable, typeEnv, typeAnalyzer, cycleChecker);
                Thunker thunker = new Thunker(thunkChecker,cycleChecker);
                thunker.walk(component_ast);
                //make sure to do toplevel functions after walking so functional methods and operators will already have thunks
                TryChecker tryChecker = STypeCheckerFactory.makeTryChecker(componentIndex,traitTable,typeEnv,typeAnalyzer, cycleChecker);
                com.sun.fortress.scala_src.typechecker.Thunker$.MODULE$.primeFunctionals(componentIndex.parametricOperators(), tryChecker, cycleChecker);
                com.sun.fortress.scala_src.typechecker.Thunker$.MODULE$.primeFunctionals(componentIndex.functions().secondSet(), tryChecker, cycleChecker);
                //Typecheck
                STypeChecker typeChecker =
                    STypeCheckerFactory.make(componentIndex, traitTable, typeEnv, log, typeAnalyzer, cycleChecker);
                ast = (Component)typeChecker.typeCheck(component_ast);
                componentIndex = (ComponentIndex)buildIndex(ast, isApi);
                errors.addAll(Lists.toJavaList(typeChecker.getErrors()));
                result = new TypeCheckerResult(ast, errors, typeChecker);


            }
            index = componentIndex;
        }
        // Pass 'false' argument to TypeNormalizer constructor to indicate that 
        // additional bounds should not be added to naked type parameters that also 
        // appear naked in the comprises clause. (That conversion is now done in
        // PreDisambiguationDesugarPhase, in order to correct a bug in checking
        // that static arguments satisfy the corresponding parameters' bounds.
        // EricAllen 4/27/2011
        result.setAst(result.ast().accept(new TypeNormalizer()));
        // There should be no Inference vars left at this point
        if( errors.isEmpty() && STypesUtil.assertAfterTypeChecking(result.ast()) )
            bug("Result of typechecking still contains intermediate nodes.\n" +
                result.ast());
        //System.out.println("WF");
        errors.addAll(new TypeWellFormedChecker(index, env, typeAnalyzer).check());
        if ( ! errors.isEmpty() ) {
            result = addErrors(errors, result);
            return result;
        }
        //System.out.println("Overloading\n");
        // Check overloadings in this compilation unit.
        errors.addAll(new OverloadingChecker(index, env).checkOverloading());
        if ( ! errors.isEmpty() ) {
            result = addErrors(errors, result);
            return result;
        }
        //System.out.println("Export\n");
        if (!isApi) {
            // Check the set of exported APIs in this component.
            errors.addAll(ExportChecker.checkExports((ComponentIndex)index, env));
            result = addErrors(errors, result);
        }

        //System.out.println("Variance\n");
        // Hack: don't run the variance checker if running the interpreter
        if (!isApi && Shell.getCompiledExprDesugaring()) { 
            errors.addAll(VarianceChecker.run((Component) result.ast()));            	
            result = addErrors(errors, result);
        }
        //System.out.println("Done\n");
        return result;
    } else {
        return new TypeCheckerResult(index.ast(), IterUtil.<StaticError>empty());
    }
}

